<script lang="ts">
 import DOMPurify from 'dompurify';
 export let html='';
 function enhance(node:HTMLElement,_html:string){let cleanup:(()=>void)[]=[];function setup(){cleanup.forEach(fn=>fn());cleanup=[];node.querySelectorAll<HTMLElement>('.checklist').forEach(list=>{const items=Array.from(list.querySelectorAll<HTMLElement>('.cl-item'));const sync=()=>{const count=list.querySelectorAll('input[type=checkbox]:checked').length;const text=list.querySelector('#cl-txt');if(text)text.textContent=count+' / '+items.length;const fill=list.querySelector<HTMLElement>('#cl-fill');if(fill)fill.style.width=count/Math.max(1,items.length)*100+'%'};items.forEach(item=>{const label=document.createElement('label');label.className=item.className;while(item.firstChild)label.append(item.firstChild);const box=label.querySelector('.cl-box')||label;box.querySelector('svg')?.remove();const input=document.createElement('input');input.type='checkbox';input.setAttribute('aria-label',label.querySelector('.cl-t')?.textContent||label.textContent||'');box.prepend(input);item.replaceWith(label);input.addEventListener('change',sync);cleanup.push(()=>input.removeEventListener('change',sync))});sync()});node.querySelectorAll('table').forEach(table=>{const wrap=document.createElement('div');wrap.className='rich-table-overflow';table.replaceWith(wrap);wrap.append(table)})}setup();return {update:setup,destroy:()=>cleanup.forEach(fn=>fn())}}
</script>
<div class="legacy-rich" use:enhance={html}>{@html DOMPurify.sanitize(html||'')}</div>
